(function(root){
 function cents(v){const s=String(v).trim();if(!/^\d{1,8}(\.\d{1,2})?$/.test(s))throw Error('金额请填写正数，最多两位小数');const [a,b='']=s.split('.'),n=Number(a)*100+Number(b.padEnd(2,'0'));if(n<=0||!Number.isSafeInteger(n))throw Error('金额必须大于零');return n}
 function date(v){if(!/^\d{4}-\d{2}-\d{2}$/.test(v))throw Error('日期格式应为 YYYY-MM-DD');const d=new Date(v+'T12:00:00');if(!Number.isFinite(+d)||key(d)!==v)throw Error('日期无效');return d}
 function key(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
 function range(period,anchor){const d=date(anchor),start=new Date(d),end=new Date(d);if(period==='week'){start.setDate(d.getDate()-(d.getDay()+6)%7);end.setTime(+start);end.setDate(start.getDate()+7)}else if(period==='month'){start.setDate(1);end.setDate(1);end.setMonth(end.getMonth()+1)}else if(period==='year'){start.setMonth(0,1);end.setMonth(0,1);end.setFullYear(end.getFullYear()+1)}else throw Error('未知周期');return {start:key(start),end:key(end)}}
 function entry(raw,id){date(raw.date);const category=String(raw.category||'其他').trim().slice(0,30),note=String(raw.note||'').trim().slice(0,200);if(!['expense','income'].includes(raw.type||'expense'))throw Error('收支类型无效');return {id,date:raw.date,cents:cents(raw.amount),category:category||'其他',note,type:raw.type||'expense'}}
 function summary(items,period,anchor){const r=range(period,anchor),rows=items.filter(x=>x.date>=r.start&&x.date<r.end),categories={};let expense=0,income=0;for(const x of rows){if(!Number.isSafeInteger(x.cents)||x.cents<=0)continue;if(x.type==='income')income+=x.cents;else{expense+=x.cents;categories[x.category]=(categories[x.category]||0)+x.cents}}return {...r,rows,expense,income,categories}}
 function csvRows(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else if(!quoted&&cell!=='')throw Error('CSV 引号格式错误');else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('CSV 引号未闭合');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows}
 function importCSV(text,id){const rows=csvRows(text.replace(/^\uFEFF/,'')),head=rows.shift()?.map(x=>x.trim());if(!head||head.join(',')!=='日期,金额,分类,备注,类型')throw Error('表头请使用：日期,金额,分类,备注,类型');if(rows.length>2000)throw Error('单次最多导入 2000 条');return rows.map((r,i)=>{try{if(r.length!==5)throw Error('需要五列');if(!['支出','收入',''].includes(r[4].trim()))throw Error('类型请填支出或收入');return entry({date:r[0].trim(),amount:r[1].trim(),category:r[2],note:r[3],type:r[4].trim()==='收入'?'income':'expense'},id(i))}catch(e){throw Error(`第 ${i+2} 行：${e.message}`)}})}
 function musicSource(value){let u;try{u=new URL(value)}catch{throw Error('请填写完整 HTTPS 链接')}if(u.protocol!=='https:'||u.username||u.password||/^(localhost|127\.|0\.|\[::1\])/.test(u.hostname))throw Error('请使用公开 HTTPS 链接');if(u.hostname==='open.spotify.com'){const m=u.pathname.match(/^\/(?:intl-[a-z]+\/)?(track|album|playlist|episode)\/([A-Za-z0-9]+)\/?$/);if(m)return {kind:'spotify',url:u.href,embed:`https://open.spotify.com/embed/${m[1]}/${m[2]}`}}if(/(^|\.)music\.163\.com$|(^|\.)163cn\.tv$/.test(u.hostname))return {kind:'netease',url:u.href};if(/(^|\.)y\.qq\.com$|(^|\.)c6\.y\.qq\.com$/.test(u.hostname))return {kind:'qq',url:u.href};if(/\.(mp3|m4a|ogg|wav|aac|flac)$/i.test(u.pathname))return {kind:'audio',url:u.href};throw Error('支持网易云、QQ 音乐、Spotify 分享链接或音频直链')}
 const api={cents,date,key,range,entry,summary,importCSV,musicSource};root.PalaisDaily=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
